// Central run config. Retargeted to privacy-regulated verticals across ALL of
// Los Angeles County (was: single point at Azusa CA, ~25mi, law/medical/trades).
//
// We want whoever can APPROVE a workflow, not whoever would use it. Apollo has
// two ways to express that and they are not equally good:
//
//   person_titles      free text, matched loosely. Asking by title returned
//                      ~40% "Office Manager" on the live LA personal-injury
//                      query - people who recommend, not people who sign.
//   person_seniorities Apollo's own normalised buckets. The same query with
//                      owner/founder/partner/c_suite returned partners,
//                      founders and CEOs.
//
// So seniority, not titles. excludeTitleRe below stays as the backstop.
//
// Directors stay in deliberately: a "Director of Intake" at a PI firm owns the
// missed-call problem, and some firms appear ONLY through their directors -
// Apollo has no owner or partner listed. Breadth costs no priority, because
// Filter & Dedupe keeps ONE person per company and keeps the most senior.
const DM_SENIORITIES = ['owner', 'founder', 'c_suite', 'partner', 'vp', 'director'];

// A SECOND pass, by explicit title, for the operational people who approve or
// veto this purchase but do not carry a senior title. They cannot be reached by
// widening the seniority list - Apollo ranks by relevance to the seniority
// band, so 'manager' returns IT Help Desk Manager, not Office Manager.
//
// Search costs no Apollo credits, so two calls per vertical costs nothing but
// wall-clock. Which of the two people represents a company is settled by the
// per-vertical ranking in Filter & Dedupe, not by which search found them.
//
// Titles below are drawn from what the live LA County preview actually
// returned per vertical, not guessed:
//   PI law          Director of Intake and COO dominated the ops pass
//   accounting      Firm Administrator, Office Manager, Controller
//   therapy         Clinical Director was the single most common title (17/50)
//   financial       Chief Compliance Officer led (9/50) - in a privacy-
//                   regulated firm, compliance owns exactly this decision
//   family office   Chief Investment Officer led (10/50)
const OPS_TITLES = {
  law_firm: ['Chief Operating Officer', 'Director of Operations', 'Firm Administrator',
           'Legal Administrator', 'Director of Intake', 'Practice Group Leader'],
  accounting_tax: ['Firm Administrator', 'Director of Operations', 'Practice Manager',
               'Office Manager', 'Controller', 'Director of Client Services'],
  therapy: ['Clinical Director', 'Practice Manager', 'Practice Administrator',
            'Office Manager', 'Director of Operations', 'Intake Coordinator'],
  financial_advisory: ['Chief Compliance Officer', 'Chief Operating Officer',
                      'Director of Operations', 'Practice Manager', 'Director of Client Services'],
  family_office: ['Chief Investment Officer', 'Chief Operating Officer',
                  'Managing Director', 'Director of Operations', 'Controller'],
};

// ALL of Los Angeles County. A single 'Los Angeles, California, US' risks
// resolving to the City of LA and quietly dropping Pasadena, Long Beach,
// Torrance and the Valley - the county is ~4,750 sq mi across 88 cities. Its
// business centres are listed explicitly instead.
//
// organization_locations (employer HQ) is the filter that matters: we sell to a
// local business. person_locations stays country-wide on purpose - an owner who
// lives outside the metro still owns the LA business.
const LA_COUNTY = [
  'Los Angeles, California, US', 'Long Beach, California, US',
  'Pasadena, California, US', 'Glendale, California, US',
  'Burbank, California, US', 'Santa Monica, California, US',
  'Torrance, California, US', 'Pomona, California, US',
  'El Segundo, California, US', 'Beverly Hills, California, US',
  'Woodland Hills, California, US', 'Culver City, California, US',
  'Encino, California, US', 'Sherman Oaks, California, US',
  'Whittier, California, US', 'Downey, California, US',
];

const apolloBase = {
  person_seniorities: DM_SENIORITIES,
  person_locations: ['United States'],
  organization_locations: LA_COUNTY,
  organization_num_employees_ranges: ['2,100'],
  contact_email_status: ['verified'],
  // 50, not 25: one firm can occupy several rows of a page, and we keep one
  // prospect per company, so a small page yields far fewer distinct businesses
  // than its size suggests. Search costs no Apollo credits; only reveals do.
  per_page: 50,
  page: 1,
};
// The ops pass filters by title INSTEAD of seniority - Apollo ANDs the two, so
// sending both would ask for an office manager who is also a founder.
const { person_seniorities: _drop, ...opsBase } = apolloBase;

// Keyword tags name what the business IS, never the market it sells into.
// Learned the hard way on the previous config: 'dental practice' returned 8/10
// vendors TO practices, because Apollo tags a company with the market it sells
// into as readily as with what it is. The risk is higher in these verticals -
// the number of vendors selling software to accountants and RIAs is enormous.
//
// serpLL: Google Maps search centre. Downtown LA at 10z spans far more of the
// county than the previous Azusa point at 11z. Family offices override this to
// the Westside, where they actually concentrate - a countywide sweep for that
// vertical is mostly wasted breadth.
const LA_CENTRE = '@34.0522,-118.2437,10z';

return [{
  json: {
    currentYear: new Date().getFullYear(),
    // Sum of the per-vertical weights below (20+12+8+6+4). Kept equal on
    // purpose: if this is lower than the sum, the LAST verticals in rank order
    // are silently starved, because verticals are processed in order.
    maxNewPerRun: 50,
    // Global fallback only. Each vertical carries its own maxThisVertical,
    // which Build Vertical Queries passes through as maxPerVertical.
    maxPerVertical: 20,
    maxRevealsPerRun: 25,
    useApollo: true,
    // Direct-dial/mobile reveal costs ~8 credits against ~1 for email, so this
    // is not "the same feature, more of it".
    maxPhoneRevealsPerRun: 0,   // direct_dial_credit is 0/2500 - reveals would
    // fail, and W1 fires them async so the failure surfaces a run later. Email
    // outreach needs no phone number. Raise this only after the cycle resets
    // (2026-09-06) and only if a calling motion actually needs it,
    excludeTitleRe: 'receptionist|paralegal|assistant|chief content|content officer|editor-in-chief|publisher',
    // Everything after 'lead gen' came from contaminants seen in live results:
    // suppliers, software, telecom, trade media. They sell INTO our verticals,
    // so they carry the same tags and survive every filter upstream of here.
    // 'institute|association|capital partners|ventures' added from the LA County
    // preview, which surfaced a psychedelic-science institute and a Cambodian
    // association under therapy, and a PE firm under financial advisors.
    excludeCompanyRe: 'marketing|agency|agencies|automation|\\bai\\b|artificial intelligence|software|saas|consult|growth partner|lead gen|supplies|\\bsupply\\b|wholesale|distribut|telecom|networking|\\bcloud\\b|\\blabs\\b|magazine|association|institute|capital partners|\\bventures\\b',
    // Ranked. Pulls start at #1 and work down; maxThisVertical weights the run
    // so priority shows up in VOLUME rather than in who gets cut off entirely.
    // Live LA County pool sizes from the preview are noted per vertical.
    verticals: [
      {
        vertical: 'law_firm',
        maxThisVertical: 20,           // pool ~489, 41 distinct companies per 50 people
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['personal injury law', 'personal injury attorney', 'trial lawyer', 'accident attorney'] },
        apolloOpsBody: { ...opsBase, q_organization_keyword_tags: ['personal injury law', 'personal injury attorney', 'trial lawyer', 'accident attorney'], person_titles: OPS_TITLES.law_firm },
        serpQuery: 'personal injury law firm Los Angeles County CA',
        serpLL: LA_CENTRE,
      },
      {
        vertical: 'accounting_tax',
        maxThisVertical: 12,           // pool ~737
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['accounting firm', 'cpa firm', 'tax preparation', 'bookkeeping services', 'tax advisory'] },
        apolloOpsBody: { ...opsBase, q_organization_keyword_tags: ['accounting firm', 'cpa firm', 'tax preparation', 'bookkeeping services', 'tax advisory'], person_titles: OPS_TITLES.accounting_tax },
        serpQuery: 'CPA accounting tax firm Los Angeles County CA',
        serpLL: LA_CENTRE,
      },
      {
        vertical: 'therapy',
        maxThisVertical: 8,            // pool ~317
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['psychotherapy', 'counseling practice', 'marriage and family therapy', 'mental health counseling', 'behavioral health clinic'] },
        apolloOpsBody: { ...opsBase, q_organization_keyword_tags: ['psychotherapy', 'counseling practice', 'marriage and family therapy', 'mental health counseling', 'behavioral health clinic'], person_titles: OPS_TITLES.therapy },
        serpQuery: 'therapy counseling practice Los Angeles County CA',
        serpLL: LA_CENTRE,
      },
      {
        vertical: 'financial_advisory',
        maxThisVertical: 6,            // pool ~1428, the largest by far
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['financial advisor', 'wealth management', 'registered investment advisor', 'financial planning firm'] },
        apolloOpsBody: { ...opsBase, q_organization_keyword_tags: ['financial advisor', 'wealth management', 'registered investment advisor', 'financial planning firm'], person_titles: OPS_TITLES.financial_advisory },
        serpQuery: 'financial advisor wealth management firm Los Angeles County CA',
        serpLL: LA_CENTRE,
      },
      {
        vertical: 'family_office',
        maxThisVertical: 4,            // pool ~564, but only 22 companies per 50
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['family office', 'multi family office', 'private wealth management'] },
        apolloOpsBody: { ...opsBase, q_organization_keyword_tags: ['family office', 'multi family office', 'private wealth management'], person_titles: OPS_TITLES.family_office },
        serpQuery: 'family office private wealth Los Angeles CA',
        // Family offices cluster on the Westside (Century City, Beverly Hills,
        // El Segundo), not countywide - a wider sweep here is dilution.
        serpLL: '@34.0577,-118.4162,11z',
      },
    ],
  },
}];

// One item per vertical carrying the API bodies + dedupe sets.
const cfg = $('Run Config').first().json;
const norm = (d) => String(d || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
const digits = (p) => String(p || '').replace(/\D/g, '').slice(-10);
const knownDomains = [];
const knownPhones = [];
for (const i of $('Get Existing Prospects').all()) {
  const d = norm(i.json && i.json.domain);
  if (d) knownDomains.push(d);
  const p = digits(i.json && i.json.contact_phone);
  if (p) knownPhones.push(p);
}
return cfg.verticals.map((v) => ({
  json: {
    vertical: v.vertical,
    apolloBody: v.apolloBody,
    apolloOpsBody: v.apolloOpsBody,
    serpQuery: v.serpQuery,
    serpLL: v.serpLL,
    knownDomains,
    knownPhones,
    // Per-vertical weighting: each vertical carries its own cap so priority
    // shows up in VOLUME. Falls back to the global for any vertical without one.
    maxPerVertical: v.maxThisVertical ?? cfg.maxPerVertical,
    useApollo: cfg.useApollo === true,
    excludeTitleRe: cfg.excludeTitleRe,
    excludeCompanyRe: cfg.excludeCompanyRe,
  },
}));

// Merge Apollo + Places candidates for this vertical, apply hard excludes,
// dedupe against the table and within the run, cap per vertical.
const ctx = $('Per Vertical').first().json;
const norm = (d) => String(d || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
const digits = (p) => String(p || '').replace(/\D/g, '').slice(-10);
const exTitle = new RegExp(ctx.excludeTitleRe, 'i');
const exCompany = new RegExp(ctx.excludeCompanyRe, 'i');
const known = new Set(ctx.knownDomains);
const knownPh = new Set(ctx.knownPhones);
const seen = new Set();
const out = [];

// Both Apollo passes: decision makers by seniority, operators by title. Either
// may be missing - the node did not run (Apollo off), or it errored and its
// output item is an error object rather than a result. Reported separately
// from a plain empty array, because "errored" and "ran fine, found nobody"
// need to stay distinguishable below - conflating them is exactly what made
// this impossible to diagnose without opening the workflow's run history.
const apolloRunInfo = (node) => {
  try {
    const j = $(node).first().json || {};
    if (j && j.error) return { people: [], errored: true };
    if (Array.isArray(j.people)) return { people: j.people, errored: false };
    return { people: [], errored: false };
  } catch (e) { return { people: [], errored: false }; }
};
const peopleInfo = apolloRunInfo('Apollo People Search');
const opsInfo = apolloRunInfo('Apollo Ops Search');
const apolloPeople = [...peopleInfo.people, ...opsInfo.people];
// Enabled, neither pass errored, and still nothing - a real, visible outcome
// in its own right, not a default we fall into unlabeled. Both a bad query
// and a broken credential used to look identical to this from the outside;
// this is what stops that.
const apolloZeroResults = ctx.useApollo === true && !peopleInfo.errored && !opsInfo.errored && apolloPeople.length === 0;
let places = $input.first().json || {};

// Surface SerpAPI failures loudly - swallowing them produced a 'successful'
// run that silently stored nothing. But loudly is not the same as fatally:
// while SerpAPI was the only source, throwing here was right; with Apollo on
// it threw away people Apollo had already returned. So the vertical fails only
// when BOTH sources came back empty.
let serpWarning = null;
if (places.error) {
  serpWarning = 'SerpAPI returned an error: ' + JSON.stringify(places.error).slice(0, 300);
} else if (!Array.isArray(places.local_results) || places.local_results.length === 0) {
  serpWarning = 'SerpAPI returned no local_results for query: ' + (ctx.serpQuery || '?') + ' | keys: ' + Object.keys(places).join(',');
}
if (serpWarning && apolloPeople.length === 0) {
  throw new Error(serpWarning);
}

// SerpAPI google_maps local_results indexed by domain (also enriches Apollo hits)
const localResults = Array.isArray(places.local_results) ? places.local_results : [];
const placeByDomain = {};
for (const p of localResults) {
  const d = norm(p.website);
  if (d) placeByDomain[d] = p;
}

// Who speaks for a company, when Apollo returns several of them. It returns
// a person per row, not a company: one live page of ten held four partners of
// the same firm. We keep one prospect per domain, and it used to be whichever
// Apollo happened to list first - so whether a firm was represented by its
// founder or by its office manager was luck. Rank instead, and keep the top.
// Who we are looking for, by vertical, because the answer genuinely differs:
//
//   law firms      managing partner or sole attorney. In larger firms a COO,
//                  Director of Operations or practice-group leader sits between
//                  them and the phones and owns this decision.
//   dental/medical the practice owner signs, but the OFFICE MANAGER runs the
//                  front desk and for back-office tools is usually the one who
//                  decides and often the one who signs. Ranked second here, not
//                  last, and that is the whole reason this is per-vertical.
//   home services  the owner, until the shop has several trucks - then whoever
//                  runs the dispatch board owns the missed call.
//
// Bands first (what the title IS), then rank and approval authority per
// vertical (what that means HERE). Order matters within AUTHORITY: 'operations'
// and 'office' are tested before the generic director and manager rules.
const AUTHORITY = [
  // (?<!vice ) on president: "Vice President Operations" is a department lead,
  // not an owner. A bare /president/ banded them with the founders, which would
  // spend a reveal credit and a call on the wrong person.
  ['owner',      /\bowner\b|founder|principal|(?<!vice )\bpresident\b|\bceo\b|chief executive|managing (partner|attorney|director)|sole (attorney|practitioner)/],
  ['operations', /\bcoo\b|chief operating|(director|vp|vice president|head)\s+(of\s+)?operations|operations (manager|director)|general manager|\bgm\b|dispatch|service manager|practice group (leader|lead)|firm administrator|legal administrator/],
  ['office',     /office manager|practice (manager|administrator)|business manager|office administrator/],
  ['c_suite',    /\bchief\b|\bcfo\b|\bcmo\b|\bcto\b|\bcso\b/],
  ['partner',    /\bpartner\b/],
  ['marketing',  /marketing|\bintake\b|growth|business development|\bbiz dev\b|client relations|revenue/],
  ['leader',     /director|\bvp\b|vice president|\bhead of\b/],
  ['staff',      /manager|administrator|coordinator/],
];
const authority = (title) => {
  const t = String(title || '').toLowerCase();
  for (const [band, re] of AUTHORITY) if (re.test(t)) return band;
  return 'staff';
};

// Higher wins the one slot a company gets, and gets the reveal credit first.
const RANK = {
  law_firm:      { owner: 9, partner: 8, operations: 7, c_suite: 6, marketing: 5, office: 4, leader: 3, staff: 2, none: 0 },
  medical:       { owner: 9, office: 8, operations: 7, c_suite: 6, marketing: 5, partner: 5, leader: 3, staff: 2, none: 0 },
  home_services: { owner: 9, operations: 8, c_suite: 6, marketing: 5, partner: 5, office: 4, leader: 3, staff: 2, none: 0 },
};
// Who can actually approve. An office manager can in a dental practice and
// cannot in a plumbing shop, which is a claim about the vertical, not the title.
const DECIDES = {
  law_firm:      new Set(['owner', 'partner', 'operations', 'c_suite', 'marketing']),
  medical:       new Set(['owner', 'office', 'operations', 'c_suite', 'marketing']),
  home_services: new Set(['owner', 'operations', 'c_suite', 'marketing']),
};
const rankOf = (title) => (RANK[ctx.vertical] || RANK.home_services)[authority(title)] || 0;
const decides = (title) => (DECIDES[ctx.vertical] || DECIDES.home_services).has(authority(title));

// Apollo has returned this object with the domain under `domain` and under
// `primary_domain` depending on the endpoint. Reading only one of them drops
// EVERY Apollo person on the `if (!domain) continue` below, silently, and the
// run still reports success - so read all three spellings.
const orgDomain = (org) => norm(org.primary_domain || org.domain || org.website_url);

const bestByDomain = new Map();
for (const person of apolloPeople) {
  const org = person.organization || {};
  const domain = orgDomain(org);
  const phone = digits(org.sanitized_phone || org.phone);
  if (!domain) continue;                                   // hard exclude: no website
  if (known.has(domain)) continue;                          // already in the table
  if (phone && knownPh.has(phone)) continue;                // dedupe on phone
  if (exTitle.test(person.title || '')) continue;           // not a decision maker
  if (exCompany.test(org.name || '')) continue;             // agencies/vendors/SaaS
  const emp = org.estimated_num_employees || null;
  if (emp !== null && emp < 2) continue;                    // solo, no staff
  const prev = bestByDomain.get(domain);
  if (!prev || rankOf(person.title) > rankOf(prev.title)) bestByDomain.set(domain, person);
}

for (const person of bestByDomain.values()) {
  const org = person.organization || {};
  const domain = orgDomain(org);
  const emp = org.estimated_num_employees || null;
  if (seen.has(domain)) continue;
  seen.add(domain);
  const place = placeByDomain[domain] || {};
  out.push({ json: {
    company_name: org.name || domain,
    vertical: ctx.vertical,
    website_url: org.website_url || 'https://' + domain,
    domain,
    contact_name: person.name || [person.first_name, person.last_name].filter(Boolean).join(' ') || null,
    contact_title: person.title || null,
    apollo_person_id: person.id || null,
    contact_authority: authority(person.title),
    decision_maker: decides(person.title),
    city: org.city || person.city || null,
    state: org.state || person.state || 'California',
    // The person first, the switchboard second, and a label saying which one
    // this is. Storing only the org number and calling it contact_phone is how
    // "call the owner" quietly became "call the front desk".
    contact_phone: person.sanitized_phone || org.sanitized_phone || org.phone || null,
    contact_phone_source: person.sanitized_phone ? 'apollo_direct' : 'apollo_company',
    company_phone: org.sanitized_phone || org.phone || null,
    contact_linkedin_url: person.linkedin_url || null,
    employee_count: emp,
    rating: place.rating ?? null,
    review_count: place.reviews ?? null,
    source: 'apollo',
  }});
}

for (const p of localResults) {
  const domain = norm(p.website);
  const phone = digits(p.phone);
  if (!domain || known.has(domain) || seen.has(domain)) continue;
  if (phone && knownPh.has(phone)) continue;
  const name = p.title || domain;
  if (exCompany.test(name)) continue;
  seen.add(domain);
  out.push({ json: {
    company_name: name,
    vertical: ctx.vertical,
    website_url: p.website,
    domain,
    contact_name: null,
    contact_title: null,
    apollo_person_id: null,
    contact_authority: 'none',
    decision_maker: false,
    city: null,
    state: 'California',
    contact_phone: p.phone || null,
    contact_phone_source: p.phone ? 'google_places' : null,
    company_phone: p.phone || null,
    contact_linkedin_url: null,
    employee_count: null,
    rating: p.rating ?? null,
    review_count: p.reviews ?? null,
    source: 'google_places',
  }});
}

const capped = out.slice(0, ctx.maxPerVertical);
// A marker, not a prospect: has no .domain, so Collect Candidates' existing
// filter drops it before it ever reaches the upsert path. It exists purely so
// 'Apollo Zero Results?' downstream can route it to a log line - it is not,
// and must never become, a row in sanaku_prospects.
const markers = apolloZeroResults ? [{ json: { _apollo_zero: true, vertical: ctx.vertical } }] : [];
return capped.length
  ? [...capped, ...markers]
  : [{ json: { _empty: true, vertical: ctx.vertical, serp_warning: serpWarning } }, ...markers];

// Flatten vertical results, drop markers, and cap the run - ROUND-ROBIN across
// verticals so one vertical can't crowd out the others under the cap.
const cfg = $('Run Config').first().json;
const all = $input.all().filter((i) => i.json && i.json.domain);
const byVertical = {};
for (const i of all) {
  (byVertical[i.json.vertical] = byVertical[i.json.vertical] || []).push(i);
}
const buckets = Object.values(byVertical);
const out = [];
let added = true;
while (out.length < cfg.maxNewPerRun && added) {
  added = false;
  for (const bucket of buckets) {
    if (out.length >= cfg.maxNewPerRun) break;
    const next = bucket.shift();
    if (next) { out.push(next); added = true; }
  }
}
return out;

// Minimal robots.txt check: honor a blanket "Disallow: /" for * or for us.
// Missing/unreachable robots.txt => allowed (standard convention).
const company = $('Per Company').first().json;
const resp = $input.first().json || {};
let allowed = true;
const txt = typeof resp === 'string' ? resp : (resp.data || resp.body || '');
if (!resp.error && typeof txt === 'string' && txt.length) {
  const lines = txt.split(/\r?\n/).map((l) => l.trim().toLowerCase());
  let applies = false;
  for (const line of lines) {
    if (line.startsWith('user-agent:')) {
      const agent = line.slice(11).trim();
      applies = agent === '*' || agent.includes('sanaku');
    } else if (applies && line.startsWith('disallow:')) {
      if (line.slice(9).trim() === '/') { allowed = false; break; }
    }
  }
}
return [{ json: { ...company, robots_allowed: allowed } }];

// Detect automation signals in the HTML, then score maturity + intent + tier.
const company = $('Check Robots').first().json;
const cfg = $('Run Config').first().json;
const resp = $input.first().json || {};
// n8n versions differ on where response text lands: body vs data.
let rawHtml = resp.body ?? resp.data ?? (typeof resp === 'string' ? resp : '');
if (rawHtml && typeof rawHtml === 'object') rawHtml = JSON.stringify(rawHtml);
const html = String(rawHtml || '').toLowerCase();
const headers = resp.headers || {};

// Category -> [name, regex] pairs. Names feed tech_stack; categories feed scoring.
const MARKERS = {
  chat: [
    ['Intercom', /widget\.intercom|intercomcdn|\bintercom\b/], ['Drift', /drift\.com|driftt\.com/],
    ['Tidio', /tidio/], ['Podium', /podiumwebchat|podium\.com/], ['Birdeye', /birdeye/],
    ['Ngage', /ngagelive|ngage\.com/], ['Smith.ai', /smith\.ai/], ['LiveChat', /livechatinc|livechat\.com/],
    ['Tawk.to', /tawk\.to/], ['ChatBot.com', /chatbot\.com|chatbotcdn/],
  ],
  booking: [
    ['Calendly', /calendly/], ['Acuity', /acuityscheduling/], ['Squarespace Scheduling', /squarespacescheduling|squarespace-scheduling/],
    ['YouCanBook.me', /youcanbook/], ['ServiceTitan', /servicetitan/], ['Housecall Pro', /housecallpro/],
    ['NexHealth', /nexhealth/], ['Zocdoc', /zocdoc/],
  ],
  crm: [
    ['HubSpot', /hs-scripts|hsforms|hubspot/], ['ActiveCampaign', /activecampaign|activehosted/],
    ['Klaviyo', /klaviyo/], ['Mailchimp', /mailchimp|chimpstatic|list-manage/],
    ['Clio Grow', /cliogrow|clio\.com/], ['Lawmatics', /lawmatics/], ['Filevine', /filevine/],
    ['Jobber', /getjobber|jobber\.com/],
  ],
  ads: [
    ['Google Ads tag', /googleadservices|gtag\(.{0,40}aw-|google_conversion/], ['Google Tag Manager', /googletagmanager/],
    ['Meta Pixel', /fbevents\.js|fbq\(/],
  ],
};

const techStack = [];
// Bot-walled or empty pages must NOT be scored - a Cloudflare challenge page
// has no widgets and would falsely read as "zero automation" (Tier 1 bait).
const blocked = html.length < 1500 ||
  /just a moment\.\.\.|attention required! \| cloudflare|cf-browser-verification|checking your browser before|enable javascript and cookies to continue/.test(html);
if (blocked) {
  return [{ json: {
    ...company,
    scored: true,
    qualified: false,
    blocked: true,
    ai_maturity_score: null,
    intent_score: null,
    tier: null,
    tech_stack: [],
    signals: { blocked: true, reason: 'site blocked automated fetch (' + html.length + ' bytes) - verify by hand before trusting any score' },
  } }];
}

const detected = {};
for (const [cat, pairs] of Object.entries(MARKERS)) {
  const hits = pairs.filter(([, re]) => re.test(html));
  if (hits.length) {
    detected[cat] = hits.map(([name]) => name);
    techStack.push(...hits.map(([name]) => name));
  }
}

const hasForm = /<form/.test(html);
const phoneVisible = /href="tel:|\(\d{3}\)\s?\d{3}[- .]\d{4}|\d{3}[-.]\d{3}[-.]\d{4}/.test(html);
const answerLanguage = /24\/7|24-7|we answer|answered? live|always (open|available)|available 24/.test(html);
const painKeywords = /call now|24\/7|free consultation|same[- ]day/.test(html);
const multiLocation = /(our|all|view) locations|locations<\/a>|serving .{0,40}(county|counties|areas)/.test(html);
const linkedinPresence = /linkedin\.com\/(in|company)\//.test(html);

const yearMatches = [...html.matchAll(/(?:\u00a9|&copy;|copyright)[^0-9]{0,20}(20\d{2})/g)].map((m) => Number(m[1]));
const copyrightYear = yearMatches.length ? Math.max(...yearMatches) : null;
let freshSite = copyrightYear !== null && copyrightYear >= cfg.currentYear - 1;
if (!freshSite && headers['last-modified']) {
  const age = (Date.now() - new Date(headers['last-modified']).getTime()) / 86400000;
  if (!Number.isNaN(age) && age <= 365) freshSite = true;
}

// Hard exclude: the site itself is an automation/marketing vendor.
if (/we build (ai|automation|chatbots)|marketing agency|lead generation (agency|company)|ai (agency|solutions for)/.test(html)) {
  return [{ json: { _excluded: true, domain: company.domain } }];
}

// --- AI maturity: 0 no automation (best) / 1 partial / 2 mature ---
let maturity = 0;
if (detected.chat) maturity = 2;
else if (detected.booking || detected.crm) maturity = 1;

// --- Intent 0-100 ---
let intent = 0;
const reasons = [];
if (detected.ads) { intent += 30; reasons.push('paying for ads (' + detected.ads.join(', ') + ')'); }
const emp = company.employee_count;
if (emp == null) { intent += 10; }  // size unknown (Places-sourced) - neutral credit, not a penalty
else if (emp >= 5 && emp <= 50) { intent += 20; reasons.push(emp + ' staff'); }
if ((company.review_count || 0) >= 25 && (company.rating || 0) >= 4.0) { intent += 15; reasons.push(company.review_count + ' Google reviews at ' + company.rating); }
if (freshSite) { intent += 10; reasons.push('site updated recently'); }
if (painKeywords) { intent += 10; reasons.push('pain language on site'); }
if (multiLocation) { intent += 10; reasons.push('multiple locations'); }
if (linkedinPresence) { intent += 5; }
intent = Math.min(100, intent);

if (maturity === 0) reasons.unshift('zero intake automation');
else if (maturity === 1) reasons.unshift('only basic tools (' + techStack.join(', ') + ')');

// --- Tier ---
let tier = 3;
if (maturity === 0 && intent >= 65) tier = 1;
else if (maturity <= 1 && intent >= 45 && intent <= 64) tier = 2;

// Scrape a contact email off the page (Places-sourced prospects have no Apollo contact).
const emailMatches = [...new Set([...html.matchAll(/[a-z0-9._%+-]+@[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,}/g)].map((m) => m[0]))]
  .filter((e) => !/\.(png|jpe?g|gif|svg|webp|css|js)$/.test(e) && !/no-?reply|sentry|wixpress|example\.|schema\.org|yourdomain|@email\.|adsadmin|godaddy|@[0-9.]+$|webcomponents|polyfill/.test(e));
const sameDomain = emailMatches.find((e) => e.endsWith('@' + company.domain));
const scrapedEmail = sameDomain || emailMatches[0] || null;

// Phone fallback: if Maps did not supply one, take it off their own site.
let scrapedPhone = null;
const telMatch = html.match(/href=\"tel:([+0-9()\-\. ]{7,20})\"/);
if (telMatch) scrapedPhone = telMatch[1].trim();
if (!scrapedPhone) {
  const m = html.match(/\(\d{3}\)\s?\d{3}[-. ]\d{4}|\b\d{3}[-.]\d{3}[-.]\d{4}\b/);
  if (m) scrapedPhone = m[0];
}

return [{ json: {
  ...company,
  contact_email: company.contact_email || scrapedEmail,
  contact_phone: company.contact_phone || scrapedPhone,
  // A tel: link on a homepage is the switchboard, never a direct line. Say so,
  // so the dashboard does not present it as the owner's number.
  company_phone: company.company_phone || scrapedPhone,
  contact_phone_source: company.contact_phone_source || (scrapedPhone ? 'website' : null),
  tech_stack: techStack,
  signals: {
    detected,
    has_contact_form: hasForm,
    phone_visible: phoneVisible,
    answer_language: answerLanguage,
    pain_keywords: painKeywords,
    multi_location: multiLocation,
    linkedin_on_site: linkedinPresence,
    copyright_year: copyrightYear,
    fresh_site: freshSite,
    rating: company.rating,
    review_count: company.review_count,
    reason: reasons.slice(0, 4).join('; '),
  },
  ai_maturity_score: maturity,
  intent_score: intent,
  tier,
  scored: true,
} }];

// Reveal decision-maker emails for prospects Apollo found, best intent first.
// HARD CAP: this is the only place in the workflow that spends Apollo credits.
//
// Tier 1 fills the cap first, then Tier 2. It used to be Tier 1 only, which
// silently wasted the difference: a run that turns up 5 Tier 1 prospects spent
// 5 of the 12 slots and left every Tier 2 prospect without an email - and W2's
// queue is filtered on contact_email IS NOT NULL, so those never get contacted
// at all. They just accumulate in the dashboard. Tier 3 is never revealed.
const cfg = $('Run Config').first().json;
const items = $input.all().map((i) => i.json);
// Within a tier, authority breaks the tie before intent does. Two prospects
// scoring the same, one an owner and one an office manager, are not equally
// worth a credit - the reveal buys a conversation, and only one of them can
// end it with a yes.
// Mirrors the per-vertical ladder in Filter & Dedupe: an office manager
// outranks a marketing director at a dental practice and does not at a
// plumbing shop, so the credit follows the vertical, not the job title.
const RANK = {
  // Who is worth a reveal credit, per vertical. Drawn from what the live LA
  // County preview actually returned, not assumed:
  //   pi_law            owner/partner signs; Director of Intake owns the problem
  //   accounting        Partner signs; Firm Administrator runs the office
  //   therapy           Clinical Director led the ops pass 17/50 - ranked above
  //                     generic operations for that reason
  //   financial_advisor Chief Compliance Officer led 9/50; in a privacy-
  //                     regulated firm compliance owns this decision, so it is
  //                     ranked directly under the owner
  //   family_office     CIO led 10/50; principal/managing director signs
  law_firm:            { owner: 9, partner: 8, operations: 7, c_suite: 6, marketing: 5, office: 4, leader: 3, staff: 2 },
  accounting_tax:        { owner: 9, partner: 8, office: 7, operations: 7, c_suite: 6, marketing: 4, leader: 3, staff: 2 },
  therapy:           { owner: 9, leader: 8, operations: 7, office: 6, c_suite: 6, partner: 5, marketing: 4, staff: 2 },
  financial_advisory: { owner: 9, c_suite: 8, partner: 7, operations: 6, office: 5, marketing: 4, leader: 4, staff: 2 },
  family_office:     { owner: 9, c_suite: 8, partner: 7, operations: 6, leader: 5, office: 4, marketing: 3, staff: 2 },
};
const rank = (x) => ((RANK[x.vertical] || RANK.law_firm)[x.contact_authority] || 0);
const byAuthorityThenIntent = (a, b) => rank(b) - rank(a) || b.intent_score - a.intent_score;
const byIntent = byAuthorityThenIntent;
const found = items.filter((x) => x.apollo_person_id);
const eligible = [
  ...found.filter((x) => x.tier === 1).sort(byIntent),
  ...found.filter((x) => x.tier === 2).sort(byIntent),
].slice(0, cfg.maxRevealsPerRun);
const revealSet = new Set(eligible.map((x) => x.domain));

// Phone is a SUBSET of the email-reveal set, never a separate selection - the
// front of the SAME best-first list, not a new one. We have already spent
// effort confirming these are the right people (verified email, real title);
// upgrading THEIR number to a real line is the highest-value use of a credit
// that costs 8x what email does. Reveal a phone for someone we did not even
// bother to email is exactly the "reach the front desk" outcome this exists
// to avoid.
const phoneRevealSet = new Set(eligible.slice(0, cfg.maxPhoneRevealsPerRun || 0).map((x) => x.domain));

return items.map((x) => ({ json: {
  ...x,
  needsReveal: revealSet.has(x.domain),
  needsPhoneReveal: phoneRevealSet.has(x.domain),
} }));

// Attach the revealed business email (never personal) to the prospect.
const company = $('Per Reveal').first().json;
const parsed = $input.first().json || {};
const person = parsed.person || {};
const email = person.email && !String(person.email).includes('email_not_unlocked') ? person.email : null;

// Apollo obfuscates/omits last names in SEARCH results unless the plan
// includes full-reveal-in-search - documented behavior, confirmed live: the
// same account, same query, returned full last names via one access path and
// first-name-only via another. contact_name was set from the search step in
// Filter & Dedupe and never revisited here, so a prospect could be stuck at
// "Steve" forever even though this very call - the one already being paid
// for - has "Steve Adler" sitting right there in the response.
//
// Only ever upgrades a partial name to a fuller one; never touches an
// already-complete name and never downgrades. If search already had the full
// name, this is a no-op.
const enrichedName = person.name || [person.first_name, person.last_name].filter(Boolean).join(' ') || null;
const looksPartial = (n) => !n || !String(n).trim().includes(' ');
const contactName = (enrichedName && looksPartial(company.contact_name) && !looksPartial(enrichedName))
  ? enrichedName
  : (company.contact_name || null);

// Phone is never in this response. Verified live twice: with
// reveal_phone_number:true the number comes back status 'pending' (async
// only); with it false there is no per-person phone field on the sync
// response at all. contact_phone/company_phone/contact_phone_source are
// therefore left exactly as they arrived via the ...company spread - the
// old code's `person.sanitized_phone` fallback checked a field that does
// not exist on a live sync response and always silently fell through.
//
// 'Apollo Enrich Person' also sends webhook_url whenever reveal_phone_number
// is true - Apollo hard-rejects the call with 400 "Please add a valid
// 'webhook_url' parameter" without it. That URL points at THIS instance's
// own 'Apollo Phone Webhook' node (migration 020), not a placeholder:
// confirmed live 2026-08 that Apollo's own request_id for this call is
// sometimes an unquoted JSON number too large to survive standard JSON
// precision (18-20 digits vs ~15-16 safe) - Apollo's OWN serializer had
// already rounded it before the response left their server, making
// 'Get Pending Phone Reveals' polling below permanently unable to find
// that request, ever, no matter how it is extracted or stored on this
// side. Apollo pushing the result here, matched back to the row by the
// person's Apollo id (a hex string, never a large number, never subject
// to this) instead of the broken numeric id, is what actually works.
// Polling stays in place as a secondary path - it still succeeds whenever
// a request_id happens not to lose precision - but the webhook push is
// now the reliable one.
//
// The pending id, if one was requested, still rides along on the row so
// polling can also try, in case it happens to resolve first.
const nowIso = new Date().toISOString();
return [{ json: {
  ...company,
  contact_name: contactName,
  contact_email: email || company.contact_email || null,
  // A SEPARATE column from contact_email, never merged into it. contact_email
  // is what W2's automated sender uses, unattended, from the same identity
  // client statements go out on - a personal inbox does not get promoted into
  // that pipeline just because Apollo happened to have one on file. Shown on
  // the dashboard; used by hand, if at all.
  contact_email_personal: parsed.personalEmail || company.contact_email_personal || null,
  contact_linkedin_url: company.contact_linkedin_url || person.linkedin_url || null,
  phone_reveal_request_id: parsed.phoneRequestId || company.phone_reveal_request_id || null,
  phone_reveal_requested_at: parsed.phoneRequestId ? nowIso : (company.phone_reveal_requested_at || null),
} }];

// Build the upsert payload + the digest email.
const items = $input.all().map((i) => i.json).filter((x) => x && x.scored);
const nowIso = new Date().toISOString();
const rows = items.map((x) => ({
  company_name: x.company_name,
  vertical: x.vertical,
  website_url: x.website_url || null,
  domain: x.domain,
  contact_name: x.contact_name || null,
  contact_title: x.contact_title || null,
  contact_email: x.contact_email || null,
  contact_phone: x.contact_phone || null,
  contact_phone_source: x.contact_phone_source || null,
  company_phone: x.company_phone || x.contact_phone || null,
  contact_linkedin_url: x.contact_linkedin_url || null,
  contact_authority: x.contact_authority || 'none',
  decision_maker: !!x.decision_maker,
  // Migration 020: a safe correlation key for the phone-reveal webhook -
  // never a large integer, so never subject to the precision loss that
  // makes phone_reveal_request_id unreliable. Was already computed by
  // Filter & Dedupe but silently dropped here before this - the webhook
  // has nothing to match an incoming push against without it.
  apollo_person_id: x.apollo_person_id || null,
  phone_reveal_request_id: x.phone_reveal_request_id || null,
  phone_reveal_requested_at: x.phone_reveal_requested_at || null,
  contact_email_personal: x.contact_email_personal || null,
  city: x.city || null,
  state: x.state || 'California',
  employee_count: x.employee_count ?? null,
  ai_maturity_score: x.ai_maturity_score,
  intent_score: x.intent_score,
  tech_stack: x.tech_stack || [],
  signals: x.signals || {},
  tier: x.tier,
  status: 'new',
  source: x.source,
}));

const byVertical = {};
for (const r of rows) byVertical[r.vertical] = (byVertical[r.vertical] || 0) + 1;
const tier1 = rows.filter((r) => r.tier === 1).sort((a, b) => b.intent_score - a.intent_score);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const top10 = tier1.slice(0, 10).map((r, i) =>
  '<tr><td style="padding:4px 8px;">' + (i + 1) + '</td>' +
  '<td style="padding:4px 8px;"><b>' + esc(r.company_name) + '</b><br>' + esc(r.domain) + '</td>' +
  '<td style="padding:4px 8px;">' + esc(r.contact_name || '-') + '<br><small>' + esc(r.contact_title || '') + '</small></td>' +
  '<td style="padding:4px 8px;">' + esc(r.contact_phone || '-') + '<br>' + esc(r.contact_email || '(no email yet)') + '</td>' +
  '<td style="padding:4px 8px;text-align:center;"><b>' + r.intent_score + '</b></td>' +
  '<td style="padding:4px 8px;">' + esc((r.signals && r.signals.reason) || '') + '</td></tr>'
).join('');

const html =
  '<h2>Sanaku scraper run - ' + nowIso.slice(0, 10) + '</h2>' +
  '<p><b>' + rows.length + '</b> new prospects stored. ' +
  Object.entries(byVertical).map(([v, n]) => v + ': ' + n).join(' | ') +
  ' | Tier 1: <b>' + tier1.length + '</b></p>' +
  (top10
    ? '<table border="1" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px;">' +
      '<tr style="background:#f5f5f5;"><th>#</th><th>Company</th><th>Contact</th><th>Phone / Email</th><th>Intent</th><th>Why they scored</th></tr>' +
      top10 + '</table>'
    : '<p>No Tier 1 prospects this run.</p>') +
  '<p>Review and approve in the Pipeline dashboard. Nothing is contacted until you approve it.</p>';

return [{ json: { rows, digestHtml: html, digestSubject: 'Sanaku: ' + rows.length + ' new prospects, ' + tier1.length + ' Tier 1 (' + nowIso.slice(0, 10) + ')' } }];

// The site refused our fetch (403 Cloudflare challenge, 404, timeout...).
// Keep the lead anyway using the Google Maps data - unscored, flagged for
// manual review. Losing a callable business because its site blocks bots
// would be the wrong trade.
const company = $('Per Company').first().json;
return [{ json: {
  ...company,
  scored: true,
  qualified: false,
  fetch_failed: true,
  ai_maturity_score: null,
  intent_score: null,
  tier: null,
  tech_stack: [],
  signals: {
    fetch_failed: true,
    rating: company.rating ?? null,
    review_count: company.review_count ?? null,
    reason: 'website blocked automated fetch - Google Maps data only; check the site by hand before calling'
  },
} }];

// n8n's text-format output lands the raw body under different keys across
// versions ('data' in current builds, 'body' in older ones) - Fetch Robots
// and Fetch Website hit the same inconsistency; same fallback here.
const item = $input.item.json || {};
let raw = item.data ?? item.body ?? (typeof item === 'string' ? item : '');
if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
raw = String(raw || '');

let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
const person = parsed.person || {};

// request_id can exceed Number.MAX_SAFE_INTEGER (a live call returned a
// 19-digit, signed value) - pulled as a STRING straight from the raw text,
// never through JSON.parse, which would round it to the wrong id.
const idMatch = raw.match(/"request_id"\s*:\s*(-?\d+)/);
const requestId = idMatch ? idMatch[1] : null;

// phone_enrichment is present ONLY when reveal_phone_number was true on this
// call. request_id itself is present on EVERY match call regardless (verified
// live with reveal_phone_number:false, which still returned a top-level
// request_id but no phone_enrichment key) - so request_id's presence cannot be
// used to decide whether a reveal was actually requested.
const phoneRequested = !!parsed.phone_enrichment;

// personal_emails is synchronous (unlike phone) and billed from the same
// lead_credit pool as the reveal call itself - confirmed live, both by the
// account's credit usage and by the field arriving inline in this same
// response with no pending/request_id involved. But its actual populated
// shape has NOT been seen live: two real owners checked both came back an
// empty array, so this only has an empty-array shape to go on. Apollo's other
// reveal arrays (mobile_phone etc.) hold OBJECTS with the value under a named
// key, not bare strings - read defensively for both, rather than assume.
const rawPersonalEmails = Array.isArray(person.personal_emails) ? person.personal_emails : [];
const firstPersonal = rawPersonalEmails.length
  ? (typeof rawPersonalEmails[0] === 'string'
      ? rawPersonalEmails[0]
      : (rawPersonalEmails[0].email || rawPersonalEmails[0].address || rawPersonalEmails[0].value || null))
  : null;

return { json: {
  person, phoneRequested, phoneRequestId: phoneRequested ? requestId : null,
  personalEmail: firstPersonal,
} };

// Decide what to do with a reveal we kicked off on a PREVIOUS run. Polling
// costs no Apollo credit either way - only the original reveal call was
// billed, back when 'Apollo Enrich Person' first requested it.
const pending = $('Per Pending Phone').first().json;

// 'Get Pending Phone Reveals' has alwaysOutputData on, so when there is
// nothing queued (the common case) it still emits one placeholder item with
// no real prospect id instead of zero items. Without this guard that
// phantom item's huge computed age (requestedAt falls back to epoch 0)
// trips the give-up branch below and 'Update Prospect Phone' ends up
// writing id=eq.<empty string>, which Postgres rejects as an invalid uuid.
// Bail out here rather than ever forwarding a blank id downstream.
if (!pending || !pending.id) {
  return { json: { resolved: false } };
}

// 'Poll Phone Reveal' sends neverError + responseFormat:text so the RAW body
// comes through no matter the status code. Confirmed live 2026-08: without
// that, n8n's own error handling on Apollo's 404 'still processing' response
// replaced the real body with a generic error object carrying no error_code
// field, which fell through the status logic below straight to 'failed' and
// gave up on every single reveal, 10 for 10 - none of them ever got the
// chance to actually finish. Parsing raw text ourselves, the same fix already
// used for 'Apollo Enrich Person', is what lets 'still pending' be told apart
// from a real failure.
const item = $input.item.json || {};
let raw = item.data ?? item.body ?? (typeof item === 'string' ? item : '');
if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
raw = String(raw || '');
let resp = {};
try { resp = JSON.parse(raw); } catch (e) { resp = {}; }

// 7 days, not Apollo's full 30-day retention window: bounded so a request
// that failed or expired on Apollo's side does not sit in the queue and get
// re-polled every run indefinitely. Comfortably survives one missed weekly
// run before giving up.
const GIVE_UP_DAYS = 7;
const requestedAt = pending.phone_reveal_requested_at ? new Date(pending.phone_reveal_requested_at).getTime() : 0;
const ageDays = (Date.now() - requestedAt) / 86400000;

const wr = resp.webhook_result || {};
const status = wr.status || (resp.error_code === 'result_pending' ? 'pending' : (resp.error ? 'failed' : 'pending'));

if (status === 'success') {
  const person = (wr.people || [])[0] || {};
  // A business-registered line first when Apollo has one; mobile as the
  // fallback that is often the ONLY number on file for a solo owner - which
  // is fine here, never invented: only what the poll actually returned.
  const pick = (arr) => (Array.isArray(arr) && arr[0] && arr[0].sanitized_number) || null;
  const number = pick(person.direct_phone) || pick(person.corporate_phone) || pick(person.mobile_phone) || pick(person.other_phone);
  return { json: { id: pending.id, resolved: true, number, giveUp: false } };
}

if (status === 'failed' || ageDays > GIVE_UP_DAYS) {
  return { json: { id: pending.id, resolved: true, number: null, giveUp: true,
    reason: status === 'failed' ? 'Apollo reported the reveal failed' : `no result after ${GIVE_UP_DAYS} days` } };
}

// still pending and not yet expired - leave it queued for the next run
return { json: { id: pending.id, resolved: false } };

// Apollo pushes a completed phone reveal here instead of us relying on
// 'Poll Phone Reveal' by request_id - that id is sometimes an unquoted JSON
// number too large for standard precision, and Apollo's OWN serializer has
// already rounded it before the response left their server (confirmed live
// 2026-08, see migration 020). This webhook sidesteps that entirely: match
// the push back to a row by the person's Apollo id instead, a normal hex
// string that is never a large number and so never has this problem.
//
// Confirmed against 10 real deliveries 2026-08: the payload is FLAT, no
// webhook_result wrapper - { status, people: [ { id, status, phone_numbers:
// [ { sanitized_number, type_cd, status_cd, confidence_cd, ... } ] } ] }.
// Different from the POLL endpoint's response shape (four separate typed
// arrays: direct_phone / corporate_phone / mobile_phone / other_phone) -
// this push instead gives ONE array per person with a type_cd tag on each
// entry. Read defensively for both shapes anyway, in case the push format
// varies by plan or changes later; 'Log Phone Webhook Received' keeps the
// full raw body regardless, so any future mismatch is visible immediately
// rather than silently dropping numbers the way this parser's first
// version did.
const item = $input.first().json || {};
const body = item.body || item;
const wr = body.webhook_result || body;
const people = Array.isArray(wr.people) ? wr.people
  : (wr.id ? [wr] : []);

// Higher wins. A direct-dial line is the person's own, same priority as
// the poll path's direct_phone; mobile next; anything else (a shared
// office/HQ line, or a type_cd not seen yet) last - still usable, just not
// preferred, same spirit as corporate_phone/other_phone in the poll path.
const TYPE_RANK = { work_direct: 3, direct: 3, mobile: 2 };
const rankType = (t) => TYPE_RANK[String(t || '').toLowerCase()] ?? 1;

const bestNumber = (p) => {
  if (Array.isArray(p.phone_numbers) && p.phone_numbers.length) {
    const valid = p.phone_numbers.filter((n) => n && n.sanitized_number && n.status_cd !== 'invalid_number');
    if (!valid.length) return null;
    valid.sort((a, b) => rankType(b.type_cd) - rankType(a.type_cd));
    return valid[0].sanitized_number;
  }
  // Poll-endpoint shape, kept as a fallback in case a future push ever uses it.
  const pick = (arr) => (Array.isArray(arr) && arr[0] && arr[0].sanitized_number) || null;
  return pick(p.direct_phone) || pick(p.corporate_phone) || pick(p.mobile_phone) || pick(p.other_phone);
};

const out = people
  .filter((p) => p && p.id)
  .map((p) => ({ json: { apollo_person_id: p.id, number: bestNumber(p) } }))
  // Never invent a number - a person with none reported yet is not this
  // webhook's job (the async job may still be running, or genuinely has
  // nothing to report); nothing to write for that item.
  .filter((x) => x.json.number);
return out;
